window.Webflow = window.Webflow || [];
Webflow.push(function () {
  var g = window.gsap, rows = document.querySelectorAll('[data-clock-tz]');
  if (!g || !rows.length) return;
  var still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var clocks = [].map.call(rows, function (row) {
    var q = function (s) { return row.querySelector(s); };
    return { f: new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23', timeZone: row.getAttribute('data-clock-tz') }),
      time: q('[data-clock-time]') || q('.office-text_time'), h: q('.clock_hand.is-hour'), m: q('.clock_hand.is-minute'), s: q('.clock_hand.is-second'), turns: 0, last: -1 };
  });
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function tick() {
    var now = new Date();
    clocks.forEach(function (k) {
      var p = {}; k.f.formatToParts(now).forEach(function (x) { p[x.type] = +x.value; });
      if (k.time) k.time.textContent = pad(p.hour) + ':' + pad(p.minute);
      if (k.h) g.set(k.h, { rotation: (p.hour % 12) * 30 + p.minute * 0.5 });
      if (k.m) g.set(k.m, { rotation: p.minute * 6 + p.second * 0.1 });
      if (k.s) { if (k.last >= 0 && p.second < k.last) k.turns++; k.last = p.second;
        var deg = (k.turns * 60 + p.second) * 6;
        if (still) g.set(k.s, { rotation: deg }); else g.to(k.s, { rotation: deg, duration: 0.35, ease: 'back.out(3)', overwrite: true }); }
    });
    g.delayedCall(1 - (Date.now() % 1000) / 1000, tick);
  }
  tick();
});

window.Webflow = window.Webflow || [];
Webflow.push(function () {
  var g = window.gsap;
  if (!g) return;
  var still = window.matchMedia('(prefers-reduced-motion: reduce)').matches, d = still ? 0 : 0.4;
  [].forEach.call(document.querySelectorAll('.navbar_menu-links'), function (nav) {
    var links = [].slice.call(nav.querySelectorAll('.navbar_menu-link'));
    if (!links.length) return;
    function colours() {
      return { base: getComputedStyle(nav).color, accent: getComputedStyle(nav).getPropertyValue('--accent-color--accent-primary').trim() || getComputedStyle(nav).color };
    }
    function focus(active) {
      var c = colours();
      links.forEach(function (l) {
        var on = l === active;
        g.to(l, { opacity: active && !on ? 0.5 : 1, x: on && !still ? 14 : 0, color: on ? c.accent : c.base, duration: d, ease: 'power3.out', overwrite: 'auto' });
      });
    }
    links.forEach(function (l) {
      l.addEventListener('mouseenter', function () { focus(l); });
      l.addEventListener('focus', function () { focus(l); });
    });
    nav.addEventListener('mouseleave', function () { focus(null); });
    nav.addEventListener('focusout', function (e) { if (!nav.contains(e.relatedTarget)) focus(null); });
  });
});

window.Webflow = window.Webflow || [];
Webflow.push(function () {
  var g = window.gsap, ST = window.ScrollTrigger;
  if (!g || !ST || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  g.registerPlugin(ST);
  var SEL = '[data-count], .home-studio_figure-number, .ledger_value, .case-results_value, .case-cards_metric-value, .case-ledger_metric';
  var NUM = /\d[\d,]*(\.\d+)?/;
  g.utils.toArray(SEL).forEach(function (el) {
    var text = el.textContent, m = text.match(NUM);
    if (!m) return;
    var raw = m[0], dec = m[1] ? m[1].length - 1 : 0, to = parseFloat(raw.replace(/,/g, '')), comma = raw.indexOf(',') > -1, pad = /^0\d/.test(raw) ? raw.length : 0, o = { v: 0 };
    function show(v) {
      var s = comma ? v.toLocaleString('en-GB', { minimumFractionDigits: dec, maximumFractionDigits: dec }) : v.toFixed(dec);
      while (s.length < pad) s = '0' + s;
      el.textContent = text.replace(raw, s);
    }
    show(0);
    g.to(o, { v: to, duration: 0.8, ease: 'power3.out', onUpdate: function () { show(o.v); }, onComplete: function () { el.textContent = text; },
      scrollTrigger: { trigger: el, start: 'top 85%', once: true } });
  });
});
